#include "study_support.h"
extern "C" int study_check(const char*path,double*met){try{auto cs=cases();for(auto&c:cs)topology(c);std::ifstream f(path,std::ios::binary);std::vector<int64_t>v(outcount(cs));f.read((char*)v.data(),v.size()*8);if(!f||f.peek()!=EOF)throw std::runtime_error("artifactsize");size_t pos=0;auto exact=[&](int64_t x){if(v.at(pos++)!=x)throw std::runtime_error("fullinput/output/path/guard");};exact(3);for(auto&c:cs){for(int h:{c.n,c.nn,c.h,c.q})exact(h);for(auto*a:{&c.nodes,&c.records,&c.keys,&c.start,&c.end})for(int32_t x:*a)exact(x);for(int a=0;a<9;a++)for(int j=0;j<c.q;j++)exact(a==2||a>=7?-777:0);}for(auto&c:cs){for(int a=0;a<2;a++)for(int32_t k:c.keys)exact(leaf(c,k));for(int32_t k:c.keys){int z=k+2*c.n;bool exists=z>=0&&z%3==0&&z/3<c.n;exact(exists?k*7+3:-777);}for(int a=0;a<4;a++)for(int j=0;j<c.q;j++)exact(leaf(c,a<2?c.start[j]:c.end[j]));for(int32_t k:c.start)exact((k+2*c.n)/3);for(int j=0;j<c.q;j++)exact((c.end[j]-c.start[j])/3+1);for(int i=0;i<1792;i++)exact(-777);}if(pos!=v.size())throw std::runtime_error("outputcount");met[0]=0;met[1]=0;return 0;}catch(std::exception&e){fprintf(stderr,"BTREE_CHECK_FAIL %s\n",e.what());return 1;}}
